<h1><?= te('Safety, learning and legal resources') ?></h1><p class="sub"><?= te('Project training, policies, acknowledgements and incident follow-up. Training certificates are not generated.') ?></p>
<?php if(can('recruiter')): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="content"><label><?= te('Resource type') ?></label><select name="kind"><option value="training"><?= te('Training') ?></option><option value="safety"><?= te('Safety') ?></option><option value="legal"><?= te('Legal / policy') ?></option></select><label><?= te('Title') ?></label><input name="title" required maxlength="190"><label><?= te('Lesson / policy text') ?></label><textarea name="content" required></textarea><label><?= te('Optional HTTPS resource link') ?></label><input name="resource_url" type="url"><button class="btn"><?= te('Publish and assign') ?></button></form><?php endif; ?>
<div class="grid g2"><?php foreach($content as $l): ?><div class="card"><span class="tag"><?= e($l['kind']) ?></span><h2><?= e($l['title']) ?></h2><p><?= nl2br(e($l['content'])) ?></p><?php if($l['resource_url']): ?><a href="<?= e($l['resource_url']) ?>" target="_blank" rel="noopener"><?= te('Open resource') ?></a><?php endif; ?><?php if($isWorker): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="complete"><input type="hidden" name="content_id" value="<?= (int)$l['id'] ?>"><?php if($l['completed_at']): ?><p>Completed <?= e($l['completed_at']) ?></p><?php else: ?><button class="btn"><?= te('Mark read / completed') ?></button><?php endif; ?></form><?php endif; ?></div><?php endforeach; ?></div>
<form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="incident"><h2><?= te('Report safety incident') ?></h2><label><?= te('Project') ?></label><select name="job_id"><?php foreach($jobs as $j): ?><option value="<?= (int)$j['id'] ?>"><?= e($j['title']) ?></option><?php endforeach; ?></select><label><?= te('Severity') ?></label><select name="severity"><option value="low"><?= te('low') ?></option><option value="medium"><?= te('medium') ?></option><option value="high"><?= te('high') ?></option></select><label><?= te('Description') ?></label><textarea name="description" required></textarea><button class="btn"><?= te('Record incident') ?></button></form>
<div class="card"><h2><?= te('Incident follow-up') ?></h2><?php foreach($incidents as $i): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="resolve"><input type="hidden" name="incident_id" value="<?= (int)$i['id'] ?>"><span><?= e($i['severity'].' · '.$i['status'].' · '.$i['description']) ?></span><?php if(can('recruiter')): ?><button class="btn sm"><?= te('Resolve') ?></button><?php endif; ?></form><?php endforeach; ?></div>
<?php if(can('recruiter')): ?><div class="card"><h2><?= te('Completion tracking') ?></h2><?php foreach($progress as $r): ?><p><?= e($r['name'].' · '.$r['title'].' · '.($r['completed_at'] ?? 'Pending')) ?></p><?php endforeach; ?></div><?php endif; ?>